import assert from 'node:assert/strict'
import { existsSync, readdirSync, readFileSync } from 'node:fs'
import { join, resolve } from 'node:path'
import test from 'node:test'

// Generated by scripts/prepare-guide-content.mjs; absent before the first build.
const GUIDE_DIR = resolve('src/content/docs/guide')

function markdownFiles(dir: string): string[] {
  return readdirSync(dir, { withFileTypes: true }).flatMap(entry => {
    const path = join(dir, entry.name)
    if (entry.isDirectory()) return entry.name === 'ultimate-guide' ? [] : markdownFiles(path)
    return entry.name.endsWith('.md') ? [path] : []
  })
}

// Same slug rule as toAnchor() in scripts/prepare-guide-content.mjs.
function toAnchor(text: string): string {
  return text
    .toLowerCase()
    .replace(/[`*_~[\](){}|\\]/g, '')
    .replace(/[^\w\s-]/g, '')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '')
}

function headingAnchors(content: string): Set<string> {
  const anchors = new Set<string>()
  let inFence = false
  for (const line of content.split('\n')) {
    if (/^\s*(```|~~~)/.test(line)) inFence = !inFence
    if (inFence) continue
    const heading = line.match(/^#{1,6}\s+(.+?)\s*#*\s*$/)
    if (heading) anchors.add(toAnchor(heading[1]))
  }
  return anchors
}

test('in-page anchors are not rewritten to an ultimate-guide chapter', { skip: !existsSync(GUIDE_DIR) }, () => {
  const offenders: string[] = []
  for (const file of markdownFiles(GUIDE_DIR)) {
    const content = readFileSync(file, 'utf8')
    const own = headingAnchors(content)
    for (const [, anchor] of content.matchAll(/\]\(\/guide\/ultimate-guide\/[^)#]*#([^)]+)\)/g)) {
      if (own.has(anchor)) offenders.push(`${file.slice(GUIDE_DIR.length + 1)}#${anchor}`)
    }
  }
  assert.deepEqual(offenders, [])
})
